DROP TABLE IF EXISTS `cache_locks`;
CREATE TABLE `cache_locks` (
  `key` varchar(191) NOT NULL,
  `owner` varchar(191) NOT NULL,
  `expiration` int(11) NOT NULL,
  PRIMARY KEY (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `categories`;
CREATE TABLE `categories` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) NOT NULL,
  `slug` varchar(191) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `group_name` varchar(191) DEFAULT NULL,
  `image` varchar(191) DEFAULT NULL,
  `meta_title` varchar(191) DEFAULT NULL,
  `meta_description` text DEFAULT NULL,
  `meta_keyword` text DEFAULT NULL,
  `order` int(11) DEFAULT NULL,
  `status` varchar(191) NOT NULL DEFAULT 'Active',
  `created_by` int(10) unsigned DEFAULT NULL,
  `updated_by` int(10) unsigned DEFAULT NULL,
  `deleted_by` int(10) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `categories` (`id`, `name`, `slug`, `description`, `group_name`, `image`, `meta_title`, `meta_description`, `meta_keyword`, `order`, `status`, `created_by`, `updated_by`, `deleted_by`, `created_at`, `updated_at`, `deleted_at`) VALUES
('1', 'Dolore', 'dolore', 'Occaecati repudiandae molestiae molestias rerum rem accusamus voluptatum in. Provident ut eveniet saepe repellendus et consequatur culpa. Quo ipsam omnis fugit molestias dignissimos. Nulla molestiae non voluptas qui perspiciatis nam.', NULL, NULL, NULL, NULL, NULL, NULL, 'Active', '1', '1', NULL, '2026-04-22 17:53:10', '2026-04-22 17:53:10', NULL),
('2', 'Aut nesciunt', 'aut-nesciunt', 'Cum ut nulla odit quaerat est nisi. Rerum assumenda atque at fugit sit. Minima ex nobis corporis fuga eos optio nobis dolor. Iste sunt similique dolore hic ut.', NULL, NULL, NULL, NULL, NULL, NULL, 'Active', '1', '1', NULL, '2026-04-22 17:53:10', '2026-04-22 17:53:10', NULL),
('3', 'Inventore qui', 'inventore-qui', 'Perspiciatis dolorem maxime fugit aliquid. Vitae ipsam dolorem qui enim minima reprehenderit.', NULL, NULL, NULL, NULL, NULL, NULL, 'Active', '1', '1', NULL, '2026-04-22 17:53:11', '2026-04-22 17:53:10', NULL),
('4', 'Est non', 'est-non', 'Voluptatibus aut illum beatae reprehenderit asperiores. Reprehenderit enim id beatae modi deserunt reprehenderit. Quo omnis quo et vel.', NULL, NULL, NULL, NULL, NULL, NULL, 'Inactive', '1', '1', NULL, '2026-04-22 17:53:11', '2026-04-22 17:53:10', NULL),
('5', 'Illo dolores', 'illo-dolores', 'Quis id nisi voluptate sunt nihil. Harum velit eveniet culpa deleniti dolores. Nobis sunt est sequi corporis ea vel dolores. Libero quis voluptas quos commodi et quod reiciendis dignissimos.', NULL, NULL, NULL, NULL, NULL, NULL, 'Inactive', '1', '1', NULL, '2026-04-22 17:53:11', '2026-04-22 17:53:10', NULL);

DROP TABLE IF EXISTS `contents`;
CREATE TABLE `contents` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `menu_item_id` bigint(20) unsigned NOT NULL,
  `title` varchar(300) NOT NULL,
  `slug` varchar(300) NOT NULL,
  `type` enum('content','file','external') DEFAULT 'content',
  `body` longtext DEFAULT NULL,
  `file_path` varchar(500) DEFAULT NULL,
  `file_name` varchar(300) DEFAULT NULL,
  `file_size` bigint(20) unsigned DEFAULT NULL,
  `file_mime` varchar(150) DEFAULT NULL,
  `external_url` varchar(1000) DEFAULT NULL,
  `status` enum('draft','published','archived') DEFAULT 'draft',
  `published_at` timestamp NULL DEFAULT NULL,
  `sort_order` int(11) DEFAULT 0,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_menu_item_id` (`menu_item_id`),
  KEY `idx_slug` (`slug`),
  KEY `idx_status` (`status`),
  KEY `idx_published_at` (`published_at`),
  CONSTRAINT `fk_contents_menu_item` FOREIGN KEY (`menu_item_id`) REFERENCES `menu_items` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `contents` (`id`, `menu_item_id`, `title`, `slug`, `type`, `body`, `file_path`, `file_name`, `file_size`, `file_mime`, `external_url`, `status`, `published_at`, `sort_order`, `created_by`, `updated_by`, `deleted_by`, `created_at`, `updated_at`, `deleted_at`) VALUES
