DROP TABLE IF EXISTS `tags`;
CREATE TABLE `tags` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) NOT NULL,
  `slug` varchar(191) DEFAULT NULL,
  `group_name` varchar(191) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `image` varchar(191) DEFAULT NULL,
  `status` varchar(191) NOT NULL DEFAULT 'Active',
  `meta_title` varchar(191) DEFAULT NULL,
  `meta_description` text DEFAULT NULL,
  `meta_keyword` text DEFAULT NULL,
  `created_by` int(10) unsigned DEFAULT NULL,
  `updated_by` int(10) unsigned DEFAULT NULL,
  `deleted_by` int(10) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `tags` (`id`, `name`, `slug`, `group_name`, `description`, `image`, `status`, `meta_title`, `meta_description`, `meta_keyword`, `created_by`, `updated_by`, `deleted_by`, `created_at`, `updated_at`, `deleted_at`) VALUES
('1', 'Facilis', 'facilis', NULL, 'Praesentium deserunt id recusandae error sapiente delectus ex. Magnam dolor sit at rem consectetur. Et tempora cumque sed nobis earum et. In facere debitis excepturi quia.', NULL, 'Inactive', NULL, NULL, NULL, '1', '1', NULL, '2026-04-22 17:53:11', '2026-04-22 17:53:11', NULL),
('2', 'Itaque', 'itaque', NULL, 'Quos est adipisci totam amet voluptatem velit similique. Et sint nihil et velit adipisci id. Qui sint ipsa nobis vero.', NULL, 'Draft', NULL, NULL, NULL, '1', '1', NULL, '2026-04-22 17:53:11', '2026-04-22 17:53:11', NULL),
('3', 'Sequi aut quo', 'sequi-aut-quo', NULL, 'Rerum nesciunt eius quasi et molestias. Quasi ut et voluptatem accusamus minus et. Voluptate fugit eos facere at iure placeat sapiente.', NULL, 'Inactive', NULL, NULL, NULL, '1', '1', NULL, '2026-04-22 17:53:11', '2026-04-22 17:53:11', NULL),
('4', 'Sed dolores', 'sed-dolores', NULL, 'Asperiores omnis corporis veritatis cum. Aut voluptate quis sed sed. Voluptatem nam hic sunt aut quis qui. Nam aliquam provident voluptatem dolores quia. Dolore autem reiciendis quia velit veritatis.', NULL, 'Inactive', NULL, NULL, NULL, '1', '1', NULL, '2026-04-22 17:53:11', '2026-04-22 17:53:11', NULL),
('5', 'Harum odit ea', 'harum-odit-ea', NULL, 'Ut consequuntur voluptate et et harum. Aut laudantium incidunt aspernatur quas officiis. Iusto reiciendis aut dolor sit culpa ut. Molestiae et eum aliquid accusantium minus reiciendis.', NULL, 'Draft', NULL, NULL, NULL, '1', '1', NULL, '2026-04-22 17:53:11', '2026-04-22 17:53:11', NULL),
('6', 'Quae rerum', 'quae-rerum', NULL, 'Similique ad dolores laboriosam non facilis dolorum. Minima rerum quia ad rerum nemo voluptatem. Vel corporis fugiat omnis ut.', NULL, 'Active', NULL, NULL, NULL, '1', '1', NULL, '2026-04-22 17:53:11', '2026-04-22 17:53:11', NULL),
('7', 'Dolorem', 'dolorem', NULL, 'Distinctio laudantium consequuntur non ut odit. Saepe ut enim quasi cupiditate dolor neque sint. Tenetur omnis doloribus beatae voluptatem hic aut consequatur commodi. A voluptatum ut occaecati incidunt. Autem accusamus et temporibus et nobis et magni.', NULL, 'Active', NULL, NULL, NULL, '1', '1', NULL, '2026-04-22 17:53:11', '2026-04-22 17:53:11', NULL),
('8', 'At delectus', 'at-delectus', NULL, 'Aut itaque illum expedita dolores corrupti asperiores quam. Placeat repellat esse ipsa voluptate sit perferendis. Ut harum rerum amet omnis magni voluptas. Voluptate dolores porro exercitationem possimus illo recusandae.', NULL, 'Draft', NULL, NULL, NULL, '1', '1', NULL, '2026-04-22 17:53:11', '2026-04-22 17:53:11', NULL),
('9', 'Eum aut dolor', 'eum-aut-dolor', NULL, 'Delectus quis in adipisci corporis optio dolorum. Excepturi sunt rerum dolores impedit tempore.', NULL, 'Active', NULL, NULL, NULL, '1', '1', NULL, '2026-04-22 17:53:11', '2026-04-22 17:53:11', NULL),
('10', 'Tenetur', 'tenetur', NULL, 'At ut possimus et alias et aut repudiandae et. Et explicabo dignissimos et sunt tenetur in sed. Est qui sapiente repellendus unde ullam. Vel et eveniet consectetur quia tempore.', NULL, 'Inactive', NULL, NULL, NULL, '1', '1', NULL, '2026-04-22 17:53:12', '2026-04-22 17:53:11', NULL);

DROP TABLE IF EXISTS `user_providers`;
CREATE TABLE `user_providers` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `provider` varchar(191) NOT NULL,
  `provider_id` varchar(191) NOT NULL,
  `avatar` varchar(191) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_providers_user_id_foreign` (`user_id`),
  CONSTRAINT `user_providers_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `username` varchar(191) DEFAULT NULL,
  `name` varchar(191) NOT NULL,
  `first_name` varchar(191) DEFAULT NULL,
  `last_name` varchar(191) DEFAULT NULL,
  `email` varchar(191) NOT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(191) NOT NULL,
  `mobile` varchar(191) DEFAULT NULL,
  `gender` varchar(191) DEFAULT NULL,
  `date_of_birth` date DEFAULT NULL,
  `address` text DEFAULT NULL,
  `bio` text DEFAULT NULL,
  `social_profiles` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`social_profiles`)),
  `avatar` varchar(191) DEFAULT NULL,
  `last_ip` varchar(191) DEFAULT NULL,
  `login_count` int(11) NOT NULL DEFAULT 0,
  `last_login` timestamp NULL DEFAULT NULL,
  `status` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `created_by` int(10) unsigned DEFAULT NULL,
  `updated_by` int(10) unsigned DEFAULT NULL,
  `deleted_by` int(10) unsigned DEFAULT NULL,
  `remember_token` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`),
  KEY `users_username_index` (`username`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `users` (`id`, `username`, `name`, `first_name`, `last_name`, `email`, `email_verified_at`, `password`, `mobile`, `gender`, `date_of_birth`, `address`, `bio`, `social_profiles`, `avatar`, `last_ip`, `login_count`, `last_login`, `status`, `created_by`, `updated_by`, `deleted_by`, `remember_token`, `created_at`, `updated_at`, `deleted_at`) VALUES
